/**
 * Optional, for later: turns text into vectors. When `supportAi` is given one, the corrections
 * found by words and topic are re-ordered by meaning. Nothing is stored.
 */
export interface Embedder {
  embed(texts: string[]): Promise<number[][]>;
}

export const URGENCY_RANK: Record<Urgency, number> = { urgent: 0, high: 1, normal: 2, low: 3 };

/**
 * The parts of Copilot's memory that need no model and no database: finding the words of a
 * question, measuring how much an agent changed a draft, and keeping customer details out of
 * what one customer's ticket teaches the drafts of another.
 */

const wordsOf = (text: string) => text.toLowerCase().match(/[\p{L}\p{N}]+/gu) ?? [];

/** The distinct words a question is found by: four letters or more, which leaves most filler out in most languages. */
export function searchTerms(text: string, max = 40): string[] {
  const terms = new Set<string>();
  for (const word of wordsOf(text)) {
    if (word.length < 4 || word.length > 40 || /^\d+$/.test(word)) continue;
    terms.add(word);
    if (terms.size >= max) break;
  }
  return [...terms];
}

/** How many of `terms` a text holds. */
export function sharedTerms(terms: string[], text: string) {
  const held = new Set(wordsOf(text));
  return terms.reduce((n, term) => n + (held.has(term) ? 1 : 0), 0);
}

/** 0 when the agent sent the draft as it was, 1 when nothing of it was left: the share of words that changed. */
export function changeRatio(draft: string, sent: string) {
  const a = wordsOf(draft).slice(0, 600);
  const b = wordsOf(sent).slice(0, 600);
  const longest = Math.max(a.length, b.length);
  if (!longest) return 0;
  // Longest common subsequence, one row at a time.
  let previous = new Array<number>(b.length + 1).fill(0);
  for (const word of a) {
    const row = [0];
    for (let j = 1; j <= b.length; j++) row[j] = word === b[j - 1] ? previous[j - 1]! + 1 : Math.max(previous[j]!, row[j - 1]!);
    previous = row;
  }
  return Math.round((1 - previous[b.length]! / longest) * 100) / 100;
}

/**
 * A lesson drawn from one customer's ticket may shape another customer's draft, so it must say
 * nothing about the first one. The model is asked for that; this checks it. A lesson is dropped
 * (returned as "") when it holds a digit, an address or a link, one of the names on the ticket,
 * or five words in a row from the conversation it came from. Losing a lesson is cheap; leaking
 * one customer's details into another's reply is not.
 */
export function safeLesson(lesson: string, from: { texts: string[]; names: string[] }): string {
  const text = lesson.replace(/\s+/g, " ").trim();
  if (!text || text.length > 240 || /^none\b/i.test(text)) return "";
  if (/\d|@|https?:|www\./i.test(text)) return "";
  const said = wordsOf(text);
  const held = new Set(said);
  for (const name of from.names) {
    for (const part of wordsOf(name)) if (part.length >= 3 && held.has(part)) return "";
  }
  const runs = new Set<string>();
  for (let i = 0; i + 5 <= said.length; i++) runs.add(said.slice(i, i + 5).join(" "));
  for (const source of from.texts) {
    const words = wordsOf(source);
    for (let i = 0; i + 5 <= words.length; i++) if (runs.has(words.slice(i, i + 5).join(" "))) return "";
  }
  return text;
}

/** Puts {name} and {company} where an approved answer still names the customer it was written for. */
export function maskNames(text: string, names: { name?: string | null; company?: string | null }) {
  let masked = text;
  for (const [value, placeholder] of [
    [names.company?.trim(), "{company}"],
    [names.name?.trim().split(/\s+/)[0], "{name}"],
  ] as const) {
    if (!value || value.length < 2) continue;
    const pattern = value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s+");
    masked = masked.replace(new RegExp(`(?<![\\p{L}\\p{N}])${pattern}(?![\\p{L}\\p{N}])`, "giu"), placeholder);
  }
  return masked;
}

export function cosine(a: number[], b: number[]) {
  let dot = 0;
  let na = 0;
  let nb = 0;
  for (let i = 0; i < Math.min(a.length, b.length); i++) {
    dot += a[i]! * b[i]!;
    na += a[i]! * a[i]!;
    nb += b[i]! * b[i]!;
  }
  return na && nb ? dot / Math.sqrt(na * nb) : 0;
}

/**
 * Where Copilot's knowledge comes from: your docs, a help center, an llms-full.txt. A source only
 * has to return articles; Tendkit syncs them into `support_knowledge` once a day and on demand.
 */

export type KnowledgeArticle = {
  /** Stable within the source, such as the file path. */
  id: string;
  title: string;
  /** Where a person reads it. Shown to agents as the draft's source. */
  url?: string | null;
  text: string;
};

export interface KnowledgeSource {
  id: string;
  load(): Promise<KnowledgeArticle[]>;
}

/**
 * Markdown or MDX files you already have, as `{ path: contents }`: read them with `fs`, or import
 * them as strings at build time where there's no file system. Titles come from frontmatter, else
 * the first heading, else the file name.
 */
export function docsFromFiles(
  files: Record<string, string>,
  options: { id?: string; /** The public URL of a file, when it has one. */ url?: (path: string) => string | null | undefined } = {}
): KnowledgeSource {
  return {
    id: options.id ?? "docs",
    async load() {
      return Object.entries(files)
        .map(([path, raw]) => {
          const { title, text } = parseMarkdown(raw);
          return { id: path, title: title ?? titleFromPath(path), url: options.url?.(path) ?? null, text };
        })
        .filter((article) => article.text);
    },
  };
}

/**
 * One text file holding all your docs, in the llms-full.txt style: every top-level `# ` heading
 * starts an article. A `Source:` or `URL:` line right under a heading becomes the article's link.
 */
export function docsFromUrl(url: string, options: { id?: string; fetch?: typeof fetch } = {}): KnowledgeSource {
  return {
    id: options.id ?? new URL(url).hostname,
    async load() {
      const response = await (options.fetch ?? fetch)(url, { headers: { accept: "text/plain, text/markdown, */*" } });
      if (!response.ok) throw new Error(`${url} answered ${response.status}`);
      return splitOnHeadings(await response.text(), url);
    },
  };
}

/** Splits an llms-full.txt-style document on its top-level headings. */
export function splitOnHeadings(document: string, fallbackUrl: string | null = null): KnowledgeArticle[] {
  const sections: { title: string; lines: string[] }[] = [];
  let fenced = false;
  for (const line of document.replace(/\r\n?/g, "\n").split("\n")) {
    if (/^\s*(```|~~~)/.test(line)) fenced = !fenced;
    const heading = !fenced ? /^# +(.+?)\s*#*$/.exec(line) : null;
    if (heading) sections.push({ title: heading[1]!.trim(), lines: [] });
    else if (sections.length) sections.at(-1)!.lines.push(line);
    else if (line.trim()) sections.push({ title: "", lines: [line] });
  }
  const seen = new Map<string, number>();
  const articles: KnowledgeArticle[] = [];
  for (const section of sections) {
    let articleUrl = fallbackUrl;
    const body = [...section.lines];
    // The link, when the file gives one in the first lines under the heading.
    for (let i = 0; i < Math.min(body.length, 4); i++) {
      const link = /^(?:source|url|link)\s*:\s*(https?:\/\/\S+)\s*$/i.exec(body[i]!.trim());
      if (link) {
        articleUrl = link[1]!;
        body.splice(i, 1);
        break;
      }
    }
    const text = tidy(body.join("\n"));
    if (!text) continue;
    const title = section.title || "Overview";
    const slug = slugify(title) || "article";
    const n = (seen.get(slug) ?? 0) + 1;
    seen.set(slug, n);
    articles.push({ id: n > 1 ? `${slug}-${n}` : slug, title, url: articleUrl, text });
  }
  return articles;
}

/** A Markdown or MDX file as plain reading text: frontmatter, imports, exports and JSX tags removed. */
export function parseMarkdown(raw: string): { title: string | null; text: string } {
  let source = raw.replace(/^﻿/, "").replace(/\r\n?/g, "\n");
  let title: string | null = null;
  const frontmatter = /^---\n([\s\S]*?)\n---\n?/.exec(source);
  if (frontmatter) {
    source = source.slice(frontmatter[0].length);
    const line = /^title\s*:\s*(.+)$/m.exec(frontmatter[1]!);
    if (line) title = line[1]!.trim().replace(/^(["'])(.*)\1$/, "$2") || null;
  }

  const out: string[] = [];
  let fenced = false;
  let skippingStatement = false;
  for (const line of source.split("\n")) {
    if (/^\s*(```|~~~)/.test(line)) {
      fenced = !fenced;
      out.push(line);
      continue;
    }
    if (fenced) {
      out.push(line);
      continue;
    }
    // MDX `import` and `export` statements, which may span lines until a blank one.
    if (skippingStatement) {
      if (!line.trim()) skippingStatement = false;
      continue;
    }
    if (/^(import|export)\s/.test(line)) {
      skippingStatement = !/;\s*$|from\s+["'][^"']+["']\s*$/.test(line) && !/^import\s+["']/.test(line);
      continue;
    }
    out.push(
      line
        .replace(/\{\/\*[\s\S]*?\*\/\}/g, "")
        // JSX and HTML tags go; what they wrap stays.
        .replace(/<\/?[A-Za-z][\w.:-]*(?:\s+[\w:-]+(?:=(?:"[^"]*"|'[^']*'|\{[^{}]*\}))?)*\s*\/?>/g, "")
    );
  }
  let text = tidy(out.join("\n"));
  // The title is stored on its own: a heading that only repeats it doesn't open the text too.
  const heading = /^# +(.+?)\s*#*(?:\n|$)/.exec(text);
  if (heading && (!title || heading[1]!.trim() === title)) {
    title = heading[1]!.trim();
    text = tidy(text.slice(heading[0].length));
  }
  return { title, text };
}

const tidy = (text: string) =>
  text
    .split("\n")
    .map((line) => line.trimEnd())
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

const slugify = (value: string) =>
  value
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);

function titleFromPath(path: string) {
  const parts = path.split("/").filter(Boolean);
  let name = (parts.pop() ?? path).replace(/\.[a-z0-9]+$/i, "");
  if (/^(index|page|readme)$/i.test(name) && parts.length) name = parts.pop()!;
  const words = name.replace(/[-_]+/g, " ").trim();
  return words ? words[0]!.toUpperCase() + words.slice(1) : path;
}
